CREATE TRIGGER kernel_runtime_signal_binding_matches
BEFORE INSERT ON agent_runtime_signals
WHEN NEW.record_kind = 'kernel_runtime_signal'
 AND (
    NEW.agent_member_id IS NULL
    OR NEW.capability_lease_id IS NULL
    OR NEW.capability_lease_digest IS NULL
    OR NEW.workspace_generation IS NULL
    OR NEW.process_epoch IS NULL
    OR NOT EXISTS (
        SELECT 1
        FROM agent_members AS member
        WHERE member.session_id = NEW.session_id
          AND member.member_id = NEW.agent_member_id
          AND member.agent_id = NEW.agent_id
          AND member.process_epoch = NEW.process_epoch
          AND member.status = 'active'
    )
    OR NOT EXISTS (
        SELECT 1
        FROM agent_capability_lease_records AS lease
        WHERE lease.lease_id = NEW.capability_lease_id
          AND lease.record_kind = 'agent_authority_lease'
          AND lease.session_id = NEW.session_id
          AND lease.agent_member_id = NEW.agent_member_id
          AND lease.agent_id = NEW.agent_id
          AND lease.workspace_generation = NEW.workspace_generation
          AND lease.authority_lease_digest = NEW.capability_lease_digest
          AND lease.authority_state = 'active'
          AND (
              lease.authority_expires_at IS NULL
              OR julianday(lease.authority_expires_at) > julianday('now')
          )
    )
 )
BEGIN
    SELECT RAISE(ABORT, 'kernel runtime signal target binding mismatch');
END;

CREATE TRIGGER kernel_runtime_signal_binding_immutable
BEFORE UPDATE ON agent_runtime_signals
WHEN OLD.record_kind = 'kernel_runtime_signal'
 AND (
    NEW.record_kind IS NOT OLD.record_kind
    OR NEW.signal_id IS NOT OLD.signal_id
    OR NEW.session_id IS NOT OLD.session_id
    OR NEW.agent_id IS NOT OLD.agent_id
    OR NEW.agent_member_id IS NOT OLD.agent_member_id
    OR NEW.capability_lease_id IS NOT OLD.capability_lease_id
    OR NEW.capability_lease_digest IS NOT OLD.capability_lease_digest
    OR NEW.workspace_generation IS NOT OLD.workspace_generation
    OR NEW.process_epoch IS NOT OLD.process_epoch
    OR NEW.enqueue_command_digest IS NOT OLD.enqueue_command_digest
 )
BEGIN
    SELECT RAISE(ABORT, 'kernel runtime signal occurrence binding is immutable');
END;

CREATE TRIGGER kernel_runtime_signal_claim_requires_exact_fence
BEFORE UPDATE ON agent_runtime_signals
WHEN NEW.record_kind = 'kernel_runtime_signal'
 AND NEW.status = 'claimed'
 AND (
    OLD.status <> 'claimed'
    OR NEW.claim_token IS NOT OLD.claim_token
 )
 AND (
    NEW.claim_token IS NULL
    OR NEW.session_lease_token IS NULL
    OR NEW.session_fencing_token IS NULL
    OR NEW.runtime_lease_generation IS NULL
    OR NOT EXISTS (
        SELECT 1
        FROM session_runtime_leases AS runtime_lease
        WHERE runtime_lease.record_kind = 'kernel_session_runtime_lease'
          AND runtime_lease.kernel_entity_id = NEW.session_id
          AND runtime_lease.lease_token = NEW.session_lease_token
          AND runtime_lease.generation = NEW.runtime_lease_generation
          AND runtime_lease.fencing_token = NEW.session_fencing_token
          AND runtime_lease.released_at IS NULL
          AND julianday(runtime_lease.expires_at) > julianday(NEW.claimed_at)
    )
    OR NOT EXISTS (
        SELECT 1
        FROM agent_capability_lease_records AS authority
        WHERE authority.lease_id = NEW.capability_lease_id
          AND authority.record_kind = 'agent_authority_lease'
          AND authority.authority_lease_digest = NEW.capability_lease_digest
          AND authority.authority_state = 'active'
          AND (
              authority.authority_expires_at IS NULL
              OR julianday(authority.authority_expires_at) > julianday(NEW.claimed_at)
          )
    )
 )
BEGIN
    SELECT RAISE(ABORT, 'kernel runtime signal claim requires exact live fences');
END;

CREATE TRIGGER kernel_runtime_signal_claimed_write_requires_exact_fence
BEFORE UPDATE ON agent_runtime_signals
WHEN OLD.record_kind = 'kernel_runtime_signal'
 AND OLD.status = 'claimed'
 AND NEW.status <> 'claimed'
 AND NOT EXISTS (
    SELECT 1
    FROM session_runtime_leases AS runtime_lease
    WHERE runtime_lease.record_kind = 'kernel_session_runtime_lease'
      AND runtime_lease.kernel_entity_id = OLD.session_id
      AND runtime_lease.lease_token = OLD.session_lease_token
      AND runtime_lease.generation = OLD.runtime_lease_generation
      AND runtime_lease.fencing_token = OLD.session_fencing_token
      AND runtime_lease.released_at IS NULL
      AND julianday(runtime_lease.expires_at) > julianday(
          COALESCE(NEW.completed_at, NEW.claimed_at)
      )
 )
BEGIN
    SELECT RAISE(ABORT, 'kernel runtime signal writeback requires exact live fence');
END;

