CREATE TRIGGER workspace_publication_intent_owner_match
BEFORE INSERT ON workspace_publication_intents
WHEN NOT EXISTS (
    SELECT 1
    FROM workspace_generation_records AS generation
    JOIN workspace_runtime_binding_records AS runtime
      ON runtime.workspace_id = generation.workspace_id
     AND runtime.generation = generation.generation
     AND runtime.session_id = generation.session_id
     AND runtime.owner_member_id = generation.owner_member_id
    JOIN agent_members AS member
      ON member.member_id = generation.owner_member_id
     AND member.session_id = generation.session_id
    JOIN agent_capability_lease_records AS lease
      ON lease.lease_id = NEW.capability_lease_id
    JOIN verified_workspace_checkpoint_records AS checkpoint
      ON checkpoint.checkpoint_id = NEW.checkpoint_id
    WHERE generation.workspace_id = NEW.workspace_id
      AND generation.session_id = NEW.session_id
      AND generation.owner_member_id = NEW.agent_member_id
      AND member.agent_id = NEW.agent_id
      AND generation.generation = NEW.workspace_generation
      AND generation.status = 'ready'
      AND lease.session_id = NEW.session_id
      AND lease.agent_member_id = NEW.agent_member_id
      AND lease.agent_id = NEW.agent_id
      AND lease.record_kind = 'agent_authority_lease'
      AND lease.authority_state = 'active'
      AND checkpoint.workspace_id = NEW.workspace_id
      AND checkpoint.workspace_generation = NEW.workspace_generation
      AND checkpoint.repository_binding_id = NEW.repository_binding_id
      AND checkpoint.repository_binding_version = NEW.repository_binding_version
      AND checkpoint.repository_id = NEW.repository_id
      AND checkpoint.commit_oid = NEW.expected_head_commit
      AND checkpoint.tree_oid = NEW.expected_tree
)
BEGIN
    SELECT RAISE(ABORT, 'publication intent owner or checkpoint identity mismatch');
END;

